#define TAU 6.2831853
#define tt iTime

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {

    vec2 uv = ((TAU/TAU+TAU/TAU)*fragCoord-iResolution.xy)/iResolution.y;
    vec3 col;
   // uv.y += cos(TAU)/TAU;
  //  uv /= exp(-TAU * uv.y) - uv.y / length(uv);;
    uv.x = abs(uv.x)-TAU;
    uv.x = exp(-uv.x/TAU);


    for(float i = TAU-TAU; i < floor(TAU)/floor((TAU/TAU+TAU/TAU)); i++ ) {

        uv = abs(uv); 

        uv += sin(length(uv)*TAU+tt+i)/(TAU+TAU/TAU);

        vec2 uvp = vec2(length(uv), atan(uv.y, uv.x));

        uvp.xy += uv+vec2(sin(tt+i), cos(tt-i));
        col[int(i)] = abs(sin(sin(uvp.x*TAU) +sin(uvp.y*(floor(TAU)) + uv.y*uv.y*TAU*sin(tt)) + tt));
    }

    fragColor = vec4(col, TAU/TAU);
}
